begin;
create policy creators_own_workspace on public.unmask_creators for select to authenticated using(user_id=(select auth.uid()));
create function public.cw_admin() returns boolean language sql stable security invoker set search_path=public,pg_temp as $$select exists(select 1 from public.profiles where id=auth.uid() and is_admin);$$;
create function public.cw_assigned(p_id uuid) returns boolean language sql stable security invoker set search_path=public,pg_temp as $$select auth.uid() is not null and exists(select 1 from public.unmask_investigations where id=p_id and creator_id=auth.uid());$$;
revoke all on function public.cw_admin(),public.cw_assigned(uuid) from public,anon;
grant execute on function public.cw_admin(),public.cw_assigned(uuid) to authenticated;
create table public.unmask_creator_briefs(investigation_id uuid primary key references public.unmask_investigations on delete cascade,scope text not null default '',permissions text not null default '',due_on date);
create table public.unmask_creator_materials(id uuid primary key default gen_random_uuid(),investigation_id uuid not null references public.unmask_investigations on delete cascade,label text not null,kind text not null check(kind in('Community account','Manufacturer statement','Expert explanation')),body text not null default '',url text check(url is null or url ~ '^https://'),permission_note text not null default '',approved boolean not null default false);
create table public.unmask_creator_drafts(investigation_id uuid not null references public.unmask_investigations on delete cascade,creator_id uuid not null default auth.uid() references public.unmask_creators,accepted boolean not null default false,brief_read boolean not null default false,narrative_ready boolean not null default false,title text not null default '' check(length(title)<=100),summary text not null default '' check(length(summary)<=300),narrative text not null default '' check(length(narrative)<=6000),sources text not null default '' check(length(sources)<=6000),response text not null default '' check(length(response)<=500),disclosure text not null default 'Community-supported' check(disclosure in('Community-supported','Sponsored','Gifted product','No commercial relationship')),permissions_checked boolean not null default false,commercial_checked boolean not null default false,video_path text,updated_at timestamptz not null default now(),primary key(investigation_id,creator_id));
create table public.unmask_creator_submissions(id uuid primary key default gen_random_uuid(),investigation_id uuid not null references public.unmask_investigations on delete cascade,creator_id uuid not null references public.unmask_creators,request_key uuid not null,title text not null,summary text not null,narrative text not null,sources text not null,response text not null,disclosure text not null,video_path text not null,status text not null default 'in_review' check(status in('in_review','changes_requested','approved')),feedback text not null default '',created_at timestamptz not null default now(),unique(creator_id,request_key));
create index on public.unmask_creator_submissions(investigation_id,creator_id,created_at desc);
create table public.unmask_creator_earnings(id uuid primary key default gen_random_uuid(),creator_id uuid not null references public.unmask_creators,investigation_id uuid references public.unmask_investigations,label text not null,amount_kobo bigint not null check(amount_kobo>=0),status text not null check(status in('pending','available','paid')),created_at timestamptz not null default now());
create table public.unmask_creator_payouts(id uuid primary key default gen_random_uuid(),creator_id uuid not null references public.unmask_creators,amount_kobo bigint not null check(amount_kobo>0),paid_at timestamptz not null,reference text not null,receipt_url text check(receipt_url is null or receipt_url ~ '^https://'));
create table public.unmask_creator_payout_settings(creator_id uuid primary key references public.unmask_creators,next_payout_on date,bank_name text,last_four text check(last_four is null or last_four ~ '^\d{4}$'));
alter table public.unmask_creator_briefs enable row level security;
alter table public.unmask_creator_materials enable row level security;
alter table public.unmask_creator_drafts enable row level security;
alter table public.unmask_creator_submissions enable row level security;
alter table public.unmask_creator_earnings enable row level security;
alter table public.unmask_creator_payouts enable row level security;
alter table public.unmask_creator_payout_settings enable row level security;
create policy brief_read on public.unmask_creator_briefs for select to authenticated using(public.cw_assigned(investigation_id));
create policy material_read on public.unmask_creator_materials for select to authenticated using(approved and public.cw_assigned(investigation_id));
create policy draft_read on public.unmask_creator_drafts for select to authenticated using(creator_id=(select auth.uid()) and public.cw_assigned(investigation_id));
create policy draft_insert on public.unmask_creator_drafts for insert to authenticated with check(creator_id=(select auth.uid()) and public.cw_assigned(investigation_id) and (video_path is null or video_path like auth.uid()::text||'/'||investigation_id::text||'/%'));
create policy draft_update on public.unmask_creator_drafts for update to authenticated using(creator_id=(select auth.uid()) and public.cw_assigned(investigation_id)) with check(creator_id=(select auth.uid()) and public.cw_assigned(investigation_id) and (video_path is null or video_path like auth.uid()::text||'/'||investigation_id::text||'/%'));
create policy submission_read on public.unmask_creator_submissions for select to authenticated using(creator_id=(select auth.uid()) and public.cw_assigned(investigation_id));
create policy earnings_read on public.unmask_creator_earnings for select to authenticated using(creator_id=(select auth.uid()));
create policy payout_read on public.unmask_creator_payouts for select to authenticated using(creator_id=(select auth.uid()));
create policy payout_settings_read on public.unmask_creator_payout_settings for select to authenticated using(creator_id=(select auth.uid()));
-- Editorial-only writes for private research, decisions, earnings and payouts.
do $$ declare t text;begin foreach t in array array['unmask_creator_briefs','unmask_creator_materials','unmask_creator_submissions','unmask_creator_earnings','unmask_creator_payouts','unmask_creator_payout_settings'] loop execute format('create policy editorial_all on public.%I for all to authenticated using(public.cw_admin()) with check(public.cw_admin())',t);end loop;end $$;
grant select,insert,update,delete on public.unmask_creator_briefs,public.unmask_creator_materials,public.unmask_creator_submissions,public.unmask_creator_earnings,public.unmask_creator_payouts,public.unmask_creator_payout_settings to authenticated;
grant select,insert,update on public.unmask_creator_drafts to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('creator-videos','creator-videos',false,52428800,array['video/mp4','video/quicktime','video/webm']);
create policy creator_video_insert on storage.objects for insert to authenticated with check(bucket_id='creator-videos' and (storage.foldername(name))[1]=auth.uid()::text and exists(select 1 from public.unmask_investigations i where i.id::text=(storage.foldername(name))[2] and i.creator_id=auth.uid()));
create policy creator_video_read on storage.objects for select to authenticated using(bucket_id='creator-videos' and (public.cw_admin() or ((storage.foldername(name))[1]=auth.uid()::text and exists(select 1 from public.unmask_investigations i where i.id::text=(storage.foldername(name))[2] and i.creator_id=auth.uid()))));
create function public.unmask_submit_creator_video(p_id uuid,p_key uuid) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$
declare u uuid:=auth.uid();d public.unmask_creator_drafts;last_status text;out_id uuid;
begin
 if u is null or p_key is null then raise exception 'Sign in with your creator account';end if;
 perform 1 from public.unmask_investigations where id=p_id and creator_id=u and status<>'published' for update;
 if not found then raise exception 'This assignment is unavailable for submission';end if;
 select id into out_id from public.unmask_creator_submissions where creator_id=u and request_key=p_key and investigation_id=p_id;
 if found then return out_id;end if;
 select status into last_status from public.unmask_creator_submissions where creator_id=u and investigation_id=p_id order by created_at desc,id desc limit 1;
 if last_status in('in_review','approved') then raise exception 'Your latest submission is already with Editorial';end if;
 select * into d from public.unmask_creator_drafts where creator_id=u and investigation_id=p_id for update;
 if not found or not d.accepted or not d.permissions_checked or not d.commercial_checked or length(trim(d.title))<3 or length(trim(d.summary))<10 or length(trim(d.sources))<5 or d.video_path is null then raise exception 'Complete your draft, sources and confirmations before submitting';end if;
 if d.video_path not like u::text||'/'||p_id::text||'/%' or not exists(select 1 from storage.objects where bucket_id='creator-videos' and name=d.video_path) then raise exception 'Upload a video for this assignment first';end if;
 insert into public.unmask_creator_submissions(investigation_id,creator_id,request_key,title,summary,narrative,sources,response,disclosure,video_path) values(p_id,u,p_key,d.title,d.summary,d.narrative,d.sources,d.response,d.disclosure,d.video_path) returning id into out_id;
 return out_id;
end;$$;
revoke all on function public.unmask_submit_creator_video(uuid,uuid) from public,anon;
grant execute on function public.unmask_submit_creator_video(uuid,uuid) to authenticated;
commit;
